import{_ as a,c as r,o as t,aj as i,aE as n}from"./chunks/framework.CDhdelVI.js";const m=JSON.parse('{"title":"French Bread","description":"A simple no-knead French bread with 70% hydration. Perfectly crispy on the outside and tender inside.","frontmatter":{"title":"French Bread","description":"A simple no-knead French bread with 70% hydration. Perfectly crispy on the outside and tender inside.","head":[["meta",{"name":"description","content":"A simple no-knead French bread with 70% hydration. Perfectly crispy on the outside and tender inside."}],["meta",{"property":"og:title","content":"French Bread"}],["meta",{"property":"og:description","content":"A simple no-knead French bread with 70% hydration. Perfectly crispy on the outside and tender inside."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/french-bread.html"}],["meta",{"property":"og:image","content":"https://kitchenratio.com/images/recipes/french-bread.jpg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"French Bread"}],["meta",{"name":"twitter:description","content":"A simple no-knead French bread with 70% hydration. Perfectly crispy on the outside and tender inside."}],["meta",{"name":"twitter:image","content":"https://kitchenratio.com/images/recipes/french-bread.jpg"}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/french-bread.html"}]]},"headers":[],"relativePath":"recipes/french-bread.md","filePath":"recipes/french-bread.md"}'),o={name:"recipes/french-bread.md"};function l(s,e,d,h,c,g){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="french-bread" tabindex="-1">French Bread <a class="header-anchor" href="#french-bread" aria-label="Permalink to “French Bread”">​</a></h1><div class="recipe-image"><img src="'+n+'" alt="French bread fresh from the oven"></div><p>A simple no-knead French bread at 70% hydration: crisp crust, tender interior, and straightforward handling. Use the <a href="https://kitchenratio.com/calculator/bread/french-bread/" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale it without changing the ratio.</p><div class="recipe-glance"><div class="recipe-glance-card"><strong>Style</strong><span>Lean no-knead bread with a crisp crust and tender interior.</span></div><div class="recipe-glance-card"><strong>Yield</strong><span>Example batch makes one medium loaf or a pair of smaller loaves.</span></div><div class="recipe-glance-card"><strong>Best For</strong><span>Cold overnight fermentation, Dutch ovens, and straightforward everyday bread.</span></div></div><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 350g</li><li><strong>Water</strong> - 245g (70% hydration)</li><li><strong>Salt</strong> - 7g (2%)</li><li><strong>Yeast</strong> - 3.5g (1%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine flour, water, salt, and yeast until a rough dough forms.</li><li>No kneading needed, just hydrate thoroughly.</li></ul><h3 id="_2-bulk-fermentation-cold" tabindex="-1">2. Bulk Fermentation (Cold) <a class="header-anchor" href="#_2-bulk-fermentation-cold" aria-label="Permalink to “2. Bulk Fermentation (Cold)”">​</a></h3><ul><li>Cover the bowl and place in the refrigerator for <strong>12-18 hours</strong>.</li><li><strong>Perform 2-3 folds every 30 minutes</strong> during the first 1-1.5 hours.</li><li><strong>Fold once more</strong> 8-12 hours before baking (usually the morning of baking).</li></ul><h3 id="_3-pre-shape" tabindex="-1">3. Pre-Shape <a class="header-anchor" href="#_3-pre-shape" aria-label="Permalink to “3. Pre-Shape”">​</a></h3><ul><li>Turn dough onto a lightly floured surface.</li><li>Divide if needed.</li><li>Pre-shape into balls or cylinders and rest <strong>20-30 minutes</strong>, tightening against counter.</li></ul><h3 id="_4-final-shape" tabindex="-1">4. Final Shape <a class="header-anchor" href="#_4-final-shape" aria-label="Permalink to “4. Final Shape”">​</a></h3><ul><li>Gently stretch and roll into rough boule shapes.</li><li>Place on parchment or floured couche. Use a bowl and towel to help hold shape during proofing.</li></ul><h3 id="_5-proofing" tabindex="-1">5. Proofing <a class="header-anchor" href="#_5-proofing" aria-label="Permalink to “5. Proofing”">​</a></h3><ul><li>Let dough proof until slightly puffy and relaxed.</li></ul><h3 id="_6-scoring-spritzing" tabindex="-1">6. Scoring &amp; Spritzing <a class="header-anchor" href="#_6-scoring-spritzing" aria-label="Permalink to “6. Scoring &amp; Spritzing”">​</a></h3><ul><li>Score with a sharp blade at a shallow angle (a bread lame like this <a href="https://amzn.to/44Rh5TZ" target="_blank" rel="noreferrer">Bread Lame</a> works great).</li><li>Lightly mist with water for a crisp crust.</li></ul><h3 id="_7-baking" tabindex="-1">7. Baking <a class="header-anchor" href="#_7-baking" aria-label="Permalink to “7. Baking”">​</a></h3><ul><li>Preheat a Dutch oven (or baking stone/steel, or something like this <a href="https://amzn.to/4oLycOs" target="_blank" rel="noreferrer">Lodge Cast Iron Combo Cooker</a>) to <strong>480°F (249°C)</strong>.</li><li>Place dough on parchment and carefully set in Dutch oven.</li><li>Reduce oven temperature to <strong>440°F (227°C)</strong>.</li><li>Bake covered <strong>25 minutes</strong>, then uncover and bake <strong>20-25 minutes</strong> more until golden.</li></ul><h3 id="_8-cooling" tabindex="-1">8. Cooling <a class="header-anchor" href="#_8-cooling" aria-label="Permalink to “8. Cooling”">​</a></h3><ul><li>Allow to cool completely before slicing.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/no-knead-vs-kneading.html">No-Knead vs Kneading</a></li><li><a href="/guides/folding.html">Folding</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div><blockquote><p><strong>Affiliate Disclaimer</strong><br> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',30)])])}const u=a(o,[["render",l]]);export{m as __pageData,u as default};
